module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, encode, jo, ja, kv, js, jint, getString, getInt, getArray, filterStrings, Json)
import std/string (split)
import std/list (length)

type Config = { appName: string, version: string, port: int, features: [string] }

pure func validPort(p: int) -> bool = p >= 1024 && p <= 65535

pure func validVersion(v: string) -> bool = length(split(v, ".")) == 3

func toConfig(obj: Json) -> Result[Config, string] =
  match (getString(obj, "app_name"), getString(obj, "version"), getInt(obj, "port"), getArray(obj, "features")) {
    (Some(name), Some(ver), Some(port), Some(fs)) => {
      let feats = filterStrings(fs);
      if not validPort(port) then Err("port out of range: ${show(port)}")
      else if not validVersion(ver) then Err("invalid version: ${ver}")
      else if length(feats) == 0 then Err("features list is empty")
      else Ok({ appName: name, version: ver, port: port, features: feats })
    },
    _ => Err("missing or invalid config fields")
  }

func loadConfig(path: string) -> Result[Config, string] ! {FS} =
  match decode(readFile(path)) {
    Ok(obj) => toConfig(obj),
    Err(e) => Err("parse error: ${e}")
  }

export func main() -> () ! {IO, FS} {
  let content = encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jint(8080)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]));
  writeFile("app_config.json", content);
  match loadConfig("app_config.json") {
    Ok(c) => println("Loaded ${c.appName} v${c.version} on port ${show(c.port)} with ${show(length(c.features))} features"),
    Err(msg) => println("Error: ${msg}")
  }
}

